script:
# Validate required fields
if not doc.opportunity_type:
    frappe.throw("Opportunity Type is required")

if not doc.pipeline_am:
    frappe.throw("Pipeline AM is required")

if not doc.customer:
    frappe.throw("Customer is required")

# Validate required fields
if not doc.opportunity:
    frappe.throw("Business Case must be linked to a sales Opportunity")

if not doc.customer:
    frappe.throw("Customer is required")

if not doc.pipeline_am:
    frappe.throw("Pipeline AM is required")

# if not doc.commercial_proposal:
#     frappe.throw("Commercial Proposal is required")

if not doc.proposal_date:
    frappe.throw("Proposal Date is required")

# Require a reason when rejected
if doc.status == "Rejected" and not doc.head_of_sales_notes:
    frappe.throw("Please enter the rejection reason in Head of Sales Notes")

# Require Expected Revenue for Renewal opportunities
if doc.opportunity:
    opportunity_type = frappe.db.get_value("Sabre Sales Opportunity", doc.opportunity, "opportunity_type")
    if opportunity_type == "Renewal" and not doc.true_expected_revenue:
        frappe.throw("Expected Revenue must be entered for Renewal opportunities")

# Validate required fields
if not doc.opportunity:
    frappe.throw("The Contract must be linked to a sales Opportunity")

if not doc.customer:
    frappe.throw("Customer is required")

if not doc.contract_type:
    frappe.throw("Contract Type is required")

if not doc.contract_date:
    frappe.throw("Contract Date is required")

if not doc.start_date:
    frappe.throw("Start Date is required")

if not doc.end_date:
    frappe.throw("End Date is required")

# Validate dates
if doc.start_date and doc.end_date:
    if doc.end_date <= doc.start_date:
        frappe.throw("End Date must be after Start Date")

# Require a reason when rejected
if doc.head_of_sales_review == "Rejected" and not doc.notes:
    frappe.throw("Please enter the rejection reason in Notes")

# Validate required fields
if not doc.opportunity:
    frappe.throw("Implementation must be linked to a sales Opportunity")

if not doc.customer:
    frappe.throw("Customer is required")

# if not doc.csm_assigned and not doc.flags.ignore_mandatory:
#     frappe.throw("CSM must be assigned")

if not doc.implementation_date:
    frappe.throw("Implementation Date is required")

if not doc.status:
    frappe.throw("Implementation Status is required")

# Validate required fields
if not doc.opportunity:
    frappe.throw("Go-Live must be linked to a sales Opportunity")

if not doc.customer:
    frappe.throw("Customer is required")

if not doc.go_live_date:
    frappe.throw("Go-Live Date is required")

if not doc.status:
    frappe.throw("Status is required")

# Auto-calculate follow-up dates
if doc.go_live_date:
    doc.follow_up_30_days = frappe.utils.add_days(doc.go_live_date, 30)
    doc.follow_up_60_days = frappe.utils.add_days(doc.go_live_date, 60)
    doc.follow_up_90_days = frappe.utils.add_days(doc.go_live_date, 90)

# التحقق من أن التغيير حدث في حقل مرحلة الكانبان
if doc.has_value_changed('pipeline_stage'):
    old_doc = doc.get_doc_before_save()
    old_stage = old_doc.pipeline_stage or "Lead"  # البداية الافتراضية
    new_stage = doc.pipeline_stage
    
    # الحل البديل والمضمون داخل الـ Server Script لجلب أدوار المستخدم الحالي
    user_roles = frappe.get_all("Has Role", filters={"parent": frappe.session.user}, pluck="role")
    
    # السماح للمسؤول (Administrator) بتخطي الشروط لأغراض التحرير والتجارب
    if "Administrator" not in user_roles:
        
        # 1. شروط مرحلة Lead
        if old_stage == "Lead":
            if new_stage == "Qualification":
                if "Sabre Account Manager" not in user_roles:
                    frappe.throw("عذراً! دورك الحالي لا يسمح بنقل الفرصة إلى مرحلة Qualification. (مطلوب: Sabre Account Manager)")
            else:
                frappe.throw(f"إجراء غير مسموح! من مرحلة Lead يمكنك فقط البدء بالـ Qualification وليس الانتقال إلى {new_stage}")

        # 2. شروط مرحلة Qualification
        elif old_stage == "Qualification":
            if new_stage in ["Closed - Lost", "Business Case"]:
                if "Sabre Account Manager" not in user_roles:
                    frappe.throw(f"عذراً! دورك لا يسمح بنقل المستند إلى {new_stage}. (مطلوب: Sabre Account Manager)")
                
                # تطبيق الشرط الخاص بنوع الفرصة البيعية
                if doc.opportunity_type not in ["Renewal", "Mix"]:
                    frappe.throw(f"شرط الانتقال غير مستوفٍ! لا يمكن نقل الفرصة إلى {new_stage} لأن نوعها ليس Renewal أو Mix.")
            else:
                frappe.throw(f"حركة غير مسموحة! من مرحلة Qualification يمكنك النقل فقط إلى Business Case أو Closed - Lost.")

        # 3. شروط مرحلة Business Case
        elif old_stage == "Business Case":
            if new_stage in ["Contract", "Qualification"]:
                if "Sabre Head Of Sales" not in user_roles:
                    frappe.throw(f"عذراً! صلاحية اتخاذ هذا الإجراء محصورة لمدير المبيعات فقط. (مطلوب: Sabre Head Of Sales)")
            else:
                frappe.throw(f"حركة غير مسموحة! من مرحلة Business Case يمكنك الاعتماد إلى Contract أو الإعادة إلى Qualification.")

        # 4. شروط مرحلة Contract
        elif old_stage == "Contract":
            if new_stage in ["Implementation", "Business Case"]:
                if "Sabre Finance Manager" not in user_roles:
                    frappe.throw(f"عذراً! صلاحية توقيع العقود أو إعادتها محصورة بالإدارة المالية. (مطلوب: Sabre Finance Manager)")
            else:
                frappe.throw(f"حركة غير مسموحة! من مرحلة Contract يمكنك النقل إلى Implementation أو الإعادة لـ Business Case.")

        # 5. شروط مرحلة Implementation
        elif old_stage == "Implementation":
            if new_stage == "Go-Live":
                if "Sabre Account Manager" not in user_roles:
                    frappe.throw("عذراً! دورك لا يسمح بتأكيد الـ Go-Live للمشروع. (مطلوب: Sabre Account Manager)")
            else:
                frappe.throw(f"حركة غير مسموحة! من مرحلة Implementation يجب الانتقال مباشرة إلى Go-Live.")

        # 6. شروط مرحلة Go-Live
        elif old_stage == "Go-Live":
            if new_stage == "Closed - Won":
                if "Sabre Finance Manager" not in user_roles:
                    frappe.throw("عذراً! إغلاق الفرصة كـ Closed - Won وصرف الفواتير يتطلب صلاحية مالية. (مطلوب: Sabre Finance Manager)")
            else:
                frappe.throw(f"حركة غير مسموحة! من مرحلة Go-Live يمكنك الإغلاق فقط كـ Closed - Won.")

existing = frappe.db.exists('Sabre Qualification Checklist', {
    'opportunity': doc.opportunity
})

if existing:
    frappe.throw('A Qualification Checklist already exists for this opportunity: ' + existing)

existing = frappe.db.exists('Sabre Contract', {
    'opportunity': doc.opportunity
})

if existing:
    frappe.throw('A Contract already exists for this opportunity: ' + existing)

existing = frappe.db.exists('Sabre Go-Live', {
    'opportunity': doc.opportunity
})

if existing:
    frappe.throw('A Go-Live already exists for this opportunity: ' + existing)

existing = frappe.db.exists('Sabre Implementation', {
    'opportunity': doc.opportunity
})

if existing:
    frappe.throw('An Implementation already exists for this opportunity: ' + existing)
